import type { ParseResult } from '../../src/parser.js';
import type { Bank, ParsedTransaction } from '../../src/types.js';

export type SmsFixtureProvenance = 'current' | 'historical' | 'synthetic';

export interface SmsFixture {
  name: string;
  sender: string;
  message: string;
  receivedAt: string;
  provenance: SmsFixtureProvenance;
  expected: ParseResult;
}

export const receivedAt = '2026-08-22T10:10:30+03:00';
const receivedInRiyadh = '2026-08-22T10:10:30.000+03:00';

function transaction(
  bank: Bank,
  values: Pick<ParsedTransaction, 'kind' | 'amountCents' | 'payee'> &
    Partial<Omit<ParsedTransaction, 'bank' | 'kind' | 'amountCents' | 'payee'>>,
): ParseResult {
  const { amountCents, kind, payee, ...overrides } = values;
  return {
    type: 'transaction',
    transaction: {
      bank,
      kind,
      accountAlias: undefined,
      amountCents,
      principalCents: undefined,
      feeCents: 0,
      payee,
      occurredAt: receivedInRiyadh,
      balanceCents: undefined,
      foreign: undefined,
      note: `Parsed ${bank} ${kind}`,
      transferCounterpartyAlias: undefined,
      billPaymentIdentifier: undefined,
      ...overrides,
    },
  };
}

function fixture(
  name: string,
  provenance: SmsFixtureProvenance,
  sender: string,
  message: string,
  expected: ParseResult,
  receipt = receivedAt,
): SmsFixture {
  return { name, provenance, sender, message, receivedAt: receipt, expected };
}

